with recursive cte0 (mq_id,mq_parentId,mq_name,mq_level,mqCycleMark,path) as (select fne1_0.id,fne1_0.parent_id,fne1_0.name,0,false,array[fne1_0.id] from folder_nodes fne1_0 where fne1_0.id in (?) union all select fne2_0.id,fne2_0.parent_id,fne2_0.name,(cte01_0.mq_level+cast(? as integer)),case when array_contains(cte01_0.path,fne2_0.id) then true else false end,cte01_0.path||array[fne2_0.id] from cte0 cte01_0,folder_nodes fne2_0 where fne2_0.parent_id=cte01_0.mq_id and cte01_0.mq_level<? and not(cte01_0.mqCycleMark)) select fne3_0.id,cte02_0.mq_level,(select min(cte03_0.mq_id) from cte0 cte03_0 where cte03_0.mq_level>?),(select min(cte04_0.mq_id) from cte0 cte04_0 where cte04_0.mqCycleMark),(select cte05_0.mq_id c0 from cte0 cte05_0 group by c0 having count(1)>? order by 1 fetch first ? rows only) from folder_nodes fne3_0 left join cte0 cte02_0 on cte02_0.mq_id=fne3_0.id and cte02_0.mq_level<=? and not(cte02_0.mqCycleMark) where fne3_0.id<=? order by 1
with recursive cte0 (mq_id,mq_parentId,mq_name,mq_level,mqCycleMark,path) as (select fne1_0.id,fne1_0.parent_id,fne1_0.name,0,false,array[fne1_0.id] from folder_nodes fne1_0 where fne1_0.id in (?) union all select fne2_0.id,fne2_0.parent_id,fne2_0.name,(cte01_0.mq_level+cast(? as integer)),case when array_contains(cte01_0.path,fne2_0.id) then true else false end,cte01_0.path||array[fne2_0.id] from cte0 cte01_0,folder_nodes fne2_0 where fne2_0.parent_id=cte01_0.mq_id and cte01_0.mq_level<? and not(cte01_0.mqCycleMark)) select count(*),(select min(cte03_0.mq_id) from cte0 cte03_0 where cte03_0.mq_level>?),(select min(cte04_0.mq_id) from cte0 cte04_0 where cte04_0.mqCycleMark),(select cte05_0.mq_id c0 from cte0 cte05_0 group by c0 having count(1)>? order by 1 fetch first ? rows only) from folder_nodes fne3_0 left join cte0 cte02_0 on cte02_0.mq_id=fne3_0.id and cte02_0.mq_level<=? and not(cte02_0.mqCycleMark) where fne3_0.id<=?
